#include <windows.h>
#include <psapi.h>
#include <stdio.h>

#pragma comment(lib, "psapi.lib")

int main() {
    DWORD needed = 0;
    EnumDeviceDrivers(nullptr, 0, &needed);
    auto bases = static_cast<LPVOID*>(LocalAlloc(LPTR, needed));
    if (bases == nullptr) {
        return 1;
    }

    if (EnumDeviceDrivers(bases, needed, &needed)) {
        printf("Driver bases: %lu\n", needed / sizeof(LPVOID));
    }

    LocalFree(bases);
    return 0;
}

